(function(){
'use strict';

const LESSON_ID='y7-t1-w2-practical-v2';
const sections=[
  {id:'welcome',label:'1 Welcome',time:'3 min'},
  {id:'starter',label:'2 Starter',time:'6 min'},
  {id:'brief',label:'3 Project brief',time:'6 min'},
  {id:'main1',label:'4 Main task 1',time:'12 min'},
  {id:'main2',label:'5 Main task 2',time:'18 min'},
  {id:'python',label:'6 Turtle preview',time:'8 min'},
  {id:'peer',label:'7 Peer test',time:'4 min'},
  {id:'plenary',label:'8 Plenary',time:'3 min'},
  {id:'review',label:'9 Review & export',time:'Final'}
];
const defaultCode=`import turtle as t

screen = t.Screen()
screen.setup(width=800, height=600)
screen.bgpic("school_map.gif")

route = t.Turtle()
route.shape("turtle")
route.color("blue")
route.pensize(5)
route.speed(3)

# The green start dot is approximately (-140, -225)
# Begin at the Main Entrance without drawing a line.
route.penup()
route.goto(-140, -225)
route.pendown()

# Add and improve your route commands below.
# In goto(x, y), x moves left/right and y moves down/up.
# Example: route.goto(-250, -225)


t.done()`;

let state=null,current=0,teacher=false,running=false,saveTimer=null;
const el=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const clean=v=>String(v||'').trim();
const keyFor=(name,klass,isTeacher)=>isTeacher?`${LESSON_ID}:teacher`:`${LESSON_ID}:${clean(klass).toLowerCase()}:${clean(name).toLowerCase()}`;
const fresh=(name,klass,isTeacher)=>({lesson:LESSON_ID,name:clean(name),klass:clean(klass),teacher:isTeacher,current:0,completed:{},answers:{},checks:{},code:defaultCode,initialCode:defaultCode,runCount:0,lastOutput:'',pythonEvidence:'',uploadedEvidence:'',activityLog:[],startedAt:new Date().toISOString(),updatedAt:new Date().toISOString()});
const storeKey=()=>keyFor(state.name,state.klass,state.teacher);
function migrateSavedState(saved){
  if(!saved)return saved;const oldMarker='# The green start dot is approximately (-315, -225)';
  if(String(saved.code||'').includes(oldMarker)){saved.code=saved.code.replace(oldMarker,'# The green start dot is approximately (-140, -225)').replace('route.goto(-315, -225)','route.goto(-140, -225)');}
  if(saved.teacher&&/route\.goto\(-315, -225\s*\n/.test(saved.code||'')){saved.code=defaultCode;saved.lastOutput='';}
  return saved;
}

function save(immediate=false){
  if(!state)return;
  clearTimeout(saveTimer);
  const act=()=>{try{state.updatedAt=new Date().toISOString();localStorage.setItem(storeKey(),JSON.stringify(state));localStorage.setItem(`${LESSON_ID}:last`,JSON.stringify({name:state.name,klass:state.klass,teacher:state.teacher}));el('save-status').textContent='Saved';}catch(e){el('save-status').textContent='Storage full — export soon';}};
  el('save-status').textContent='Saving…';
  if(immediate)act();else saveTimer=setTimeout(act,350);
}
function log(kind,id,value){if(!state)return;state.activityLog.push({at:new Date().toISOString(),kind,id,value:String(value??'').slice(0,160)});if(state.activityLog.length>500)state.activityLog.shift();save();}
function answer(id,fallback=''){return state.answers[id]??fallback}
function checked(id){return !!state.checks[id]}
function valueOf(id){const n=el(id);return n?(n.type==='checkbox'||n.type==='radio'?n.checked:n.value):''}
function collectVisible(){
  document.querySelectorAll('#section-host [data-answer]').forEach(n=>state.answers[n.dataset.answer]=n.value);
  document.querySelectorAll('#section-host [data-check]').forEach(n=>state.checks[n.dataset.check]=n.checked);
  const code=el('python-code');if(code)state.code=code.value;
  save();
}
function bindInputs(){
  document.querySelectorAll('[data-answer]').forEach(n=>{if(n.type==='radio'){n.checked=answer(n.dataset.answer)===n.value}else{n.value=answer(n.dataset.answer)}n.addEventListener('input',()=>{state.answers[n.dataset.answer]=n.value;log('input',n.dataset.answer,n.value)});n.addEventListener('change',()=>{state.answers[n.dataset.answer]=n.value;log('change',n.dataset.answer,n.value)})});
  document.querySelectorAll('[data-check]').forEach(n=>{n.checked=checked(n.dataset.check);n.addEventListener('change',()=>{state.checks[n.dataset.check]=n.checked;log('check',n.dataset.check,n.checked)})});
  document.querySelectorAll('.lesson-image').forEach(img=>img.addEventListener('click',()=>openImage(img)));
  document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action,b)));
}
function qText(id,label,rows=3,placeholder='Type your answer here…'){return `<div class="question"><label for="${id}">${label}</label><textarea id="${id}" rows="${rows}" data-answer="${id}" placeholder="${placeholder}"></textarea></div>`}
function qInput(id,label,placeholder=''){return `<div class="question"><label for="${id}">${label}</label><input id="${id}" data-answer="${id}" placeholder="${placeholder}"></div>`}
function check(id,text){return `<label class="check-row"><input type="checkbox" data-check="${id}"><span>${text}</span></label>`}
function image(file,alt){return `<img class="lesson-image" src="assets/${file}" alt="${esc(alt)}" loading="lazy" title="Select to enlarge">`}
function sectionHeader(title,time,intro){return `<header><p class="eyebrow">${time}</p><h2>${title}</h2><p>${intro}</p></header>`}

const renderers={
welcome(){return `${sectionHeader('Welcome and setup','4 minutes','Know today’s job and prepare your project folder.')}<div class="card-grid"><article class="lesson-card"><span class="read-tag">Today’s job</span><h3>Help a new student find the CS room</h3><p>Imagine it is your first day at this school. You are standing at the <strong>Main Entrance</strong>, but you do not know how to reach <strong>CS Room C1</strong>.</p><p>Your job is to write clear directions and use Python Turtle to draw part of the journey on a map.</p><div class="callout"><strong>You are making:</strong> route instructions and a line on a map. You are not making a live phone navigation app.</div></article><article class="lesson-card"><span class="read-tag">Prepare</span><h3>Project folder</h3><pre class="code-review">Computing
└── Year 7
    └── Term 1
        └── T1.1 Computational Thinking and Turtle</pre><p>Suggested Python filename:</p><p><strong>${esc(filename('WayfindingPlan','py'))}</strong></p>${check('welcome_folder','I have found or created the correct project folder.')}${check('welcome_wagba','I understand that I will plan directions, test them and draw part of the route with Python Turtle.')}${check('welcome_files','I will save my work using the filename shown above.')}</article></div>`},
starter(){return `${sectionHeader('Starter — Three useful ideas','7 minutes','Read one short idea at a time, then answer the question below it.')}<div class="card-grid"><article class="lesson-card"><span class="read-tag">Idea 1</span><h3>Split a big journey into small parts</h3><p>A journey across the whole school can feel difficult. Make it easier by splitting it:</p><p><strong>Main Entrance → Reception → Library → Stairs → CS Room.</strong></p><p>Computer scientists call this <strong>decomposition</strong>.</p>${qText('starter_decomp','What does “split the problem” mean for this journey?',2,'It means…')}</article><article class="lesson-card"><span class="read-tag">Idea 2</span><h3>Keep only useful map details</h3><p>A new student needs room names, corridors, doors, turns and places they cannot enter. They do not need to see every chair, window or decoration.</p><p>Computer scientists call this <strong>abstraction</strong>: simplify the map so the important parts are easy to see.</p>${qText('starter_abstract','Write two details the map needs and one detail it does not need.',2,'The map needs… It does not need…')}</article><article class="lesson-card full"><span class="read-tag">Idea 3</span><h3>What goes in, what happens, what comes out?</h3><ul><li><strong>Input:</strong> the map and route numbers used by the program.</li><li><strong>Process:</strong> Python follows the instructions and moves Turtle.</li><li><strong>Output:</strong> a route line appears on the map.</li></ul><p>We shorten this to <strong>IPO</strong>: Input → Process → Output.</p>${qInput('starter_ipo','Complete the missing part: route numbers → ______ → route line','Python moves Turtle')}</article><article class="lesson-card full"><h3>Quick check</h3><fieldset class="question"><legend>Which map would help a new student most?</legend><label class="choice"><input type="radio" name="abstraction-choice" value="all" data-answer="starter_choice"> A map showing every chair, window and noticeboard.</label><label class="choice"><input type="radio" name="abstraction-choice" value="useful" data-answer="starter_choice"> A map showing the corridors, room names, doors and STAFF ONLY area.</label><label class="choice"><input type="radio" name="abstraction-choice" value="none" data-answer="starter_choice"> A blank map with no room names.</label></fieldset><button class="small-button" data-action="check-starter">Check my answer</button><div id="starter-feedback" class="feedback hidden" role="status"></div></article></div>`},
brief(){return `${sectionHeader('Your task — What are you making?','7 minutes','Read the situation, then explain the job in your own words.')}<div class="card-grid"><article class="lesson-card full"><div class="scenario"><h3>Imagine this is your first day</h3><p>You enter the school through the <strong>Main Entrance</strong>. Your next lesson is in <strong>CS Room C1</strong>, but you have never been there.</p><p>You need simple directions and a line on a map. The line must stay in the corridors and must not enter <strong>STAFF ONLY</strong>.</p><p><strong>Your job:</strong> plan the directions, then use Python Turtle to draw part of the safe route.</p></div></article><article class="lesson-card"><h3>Explain the job</h3>${qInput('brief_user','Who are you helping?','A new Year 7 student')}${qText('brief_purpose','Why does this student need your route?',2,'They need the route because…')}${qText('brief_product','What will you make today? Mention written directions, the map and the Turtle line.',3,'I will make…')}</article><article class="lesson-card"><h3>How will you know it works?</h3><p>Write four short sentences beginning with <strong>“The route must…”</strong> Another student should be able to check each sentence by looking at the map.</p>${qInput('criteria_1','1. Where must it start?','The route must start at the green dot by the Main Entrance.')}${qInput('criteria_2','2. Where must it finish?','The route must finish at the blue dot by CS Room C1.')}${qInput('criteria_3','3. Which place must it avoid?','The route must not enter the STAFF ONLY area.')}${qInput('criteria_4','4. What must the line follow?','The route must stay inside the corridors and must not cross walls.')}</article></div>`},
main1(){return `${sectionHeader('Main Task 1 — Input, Process, Output','10 minutes','Explain what the program uses, what it does and what it shows.')}<div class="card-grid"><article class="lesson-card"><span class="read-tag">Example</span><h3>Think about a drinks machine</h3><p><strong>Input:</strong> you press a drink button.</p><p><strong>Process:</strong> the machine prepares the drink.</p><p><strong>Output:</strong> the drink comes out.</p><p>Our route program works in the same three stages.</p></article><article class="lesson-card"><h3>Your route program</h3><p><strong>Input:</strong> the map and the coordinate numbers in the code.</p><p><strong>Process:</strong> Python reads each command and moves Turtle.</p><p><strong>Output:</strong> Turtle draws a route line on the map.</p>${qText('ipo_input','INPUT — What will the program use?',2,'The program will use…')}${qText('ipo_process','PROCESS — What will Python Turtle do?',2,'Python Turtle will…')}${qText('ipo_output','OUTPUT — What will appear on the screen?',2,'The screen will show…')}</article></div>`},
main2(){return `${sectionHeader('Main Task 2 — Split the journey and write directions','16 minutes','Plan one small part at a time, then join the directions together.')}<div class="card-grid"><article class="lesson-card"><span class="read-tag">Step 1</span><h3>Split the journey</h3><p>Do not try to plan the whole journey at once. Split it into four smaller journeys:</p><ol><li>Main Entrance → Reception</li><li>Reception → Library</li><li>Library → Main Stairs</li><li>Main Stairs → Science Corridor → CS Room C1</li></ol><p>Computer scientists call this <strong>decomposition</strong>. Use places that are easy to recognise, such as a named room, the stairs or a corridor.</p></article><article class="lesson-card"><span class="read-tag">Step 2</span><h3>Write directions before Python</h3><p>Write one clear action on each line. Computer scientists call these planning instructions <strong>pseudocode</strong>.</p><pre class="code-review">START at the Main Entrance
MOVE east to Reception
TURN left at Reception
MOVE north towards Library
...
STOP at CS Room C1</pre><p>Pseudocode is not Python code. It is a simple plan that another person can read and test.</p></article><article class="lesson-card full"><h3>Plan your four small journeys</h3><table class="route-table"><thead><tr><th>Part</th><th>Start at</th><th>What should the student do?</th><th>Finish at</th></tr></thead><tbody>${[1,2,3,4].map(i=>`<tr><th>${i}</th><td><input aria-label="Part ${i} start" data-answer="route_${i}_start" placeholder="For example: Reception"></td><td><input aria-label="Part ${i} action" data-answer="route_${i}_move" placeholder="For example: turn left and walk along the corridor"></td><td><input aria-label="Part ${i} finish" data-answer="route_${i}_end" placeholder="For example: Library"></td></tr>`).join('')}</tbody></table>${qText('pseudocode','Now join your plan into 6–10 short directions. Start at the Main Entrance and end at CS Room C1.',9,'START at the Main Entrance…')}</article><article class="lesson-card"><h3>Check your plan against the map</h3><p>Look for the named rooms, doors, stairs, corridors and STAFF ONLY area.</p>${qText('map_plan','Describe your safe route using places a new student can easily recognise.',3,'From the Main Entrance, go towards…')}</article><article class="lesson-card"><h3>Optional: add your marked map</h3><p>If you drew the route on paper or marked a digital map, add a photo or screenshot here.</p><label for="evidence-upload">Add map image</label><input id="evidence-upload" type="file" accept="image/*"><img id="upload-preview" class="upload-preview hidden" alt="Student’s uploaded route plan"><button class="small-button" data-action="remove-upload">Remove image</button><p id="upload-message" class="feedback hidden"></p></article></div>`},
python(){return `${sectionHeader('Turtle preview — Turn part of the plan into code','8 minutes','Use the built-in Python editor to preview and improve the planned route.')}<div class="lesson-card full"><p class="callout"><strong>This is a preview, not the full Week 3 implementation.</strong> The background is already placed beneath Turtle’s transparent drawing canvas. In this editor, the map is 800 × 600 pixels and Turtle uses <strong>(0, 0)</strong> at its centre.</p><div class="coordinate-help"><h3>How to read <code>goto(x, y)</code></h3><p><strong>x comes first:</strong> negative x moves left; positive x moves right. <strong>y comes second:</strong> negative y moves down; positive y moves up.</p><p>Example: <code>route.goto(-250, -225)</code> means move to x = −250 and y = −225.</p></div><ul class="success-list"><li>Run the starter code.</li><li>Use the coordinate grid and pointer readout to choose route points.</li><li>Add at least three route movement commands using <code>goto(x, y)</code>, <code>forward()</code> or turns.</li><li>Keep the route away from STAFF ONLY.</li><li>Capture evidence and download the Python file.</li></ul><div class="ide-shell"><div class="ide-toolbar"><button class="primary" data-action="run-python">Run <span aria-hidden="true">▶</span></button><button class="secondary" data-action="stop-python">Stop</button><button class="secondary" data-action="toggle-grid" aria-pressed="true">Hide coordinate grid</button><button class="secondary" data-action="reset-python">Reset code</button><button class="secondary" data-action="clear-output">Clear output</button><button class="secondary" data-action="download-python">Download .py</button><button class="secondary" data-action="capture-python">Capture evidence</button></div><div class="coordinate-readout" id="coordinate-readout" role="status">Move the pointer over the map to read x and y. Select the map to copy a <code>route.goto(x, y)</code> command.</div><div class="ide-grid"><div class="editor-pane"><label class="sr-only" for="python-code">Python code</label><textarea id="python-code" class="code-editor" spellcheck="false" aria-label="Python code editor"></textarea><div id="python-console" class="console" role="log">Python Turtle is ready.</div></div><div class="turtle-pane"><div id="turtle-stage" class="turtle-stage"><img src="assets/school_map_800x600.png" alt="School map background"><canvas id="coordinate-grid" class="coordinate-grid" width="800" height="600" aria-hidden="true"></canvas><div id="turtle-output" class="turtle-output" aria-label="Turtle graphics output"></div><div id="coordinate-crosshair" class="coordinate-crosshair hidden" aria-hidden="true"><span></span></div><div id="map-cover" class="map-cover">Select Run to draw your route over the map. The coordinate grid is already available.</div></div></div></div></div><p><strong>Background image note:</strong> the visible map is loaded by the webpage. The editor recognises <code>screen.bgpic("school_map.gif")</code> and preserves it in the downloaded Python file for use in desktop Python.</p>${qText('python_explain','Explain how your code represents at least one section of your planned route.',3)}${qText('python_improve','What did you change after viewing the route on the map?',2)}<img id="python-evidence" class="evidence-preview hidden" alt="Captured Python code and Turtle map evidence"></div>`},
peer(){return `${sectionHeader('Ask a partner to test your directions','4 minutes','Your partner must follow what you wrote without guessing what you meant.')}<div class="card-grid"><article class="lesson-card"><h3>Partner instructions</h3><ol><li>Read the first direction aloud.</li><li>Use a finger to follow it on the map.</li><li>Stop if you do not know where to go.</li><li>Tell the writer which words were confusing.</li><li>The writer changes that direction.</li><li>Follow the changed direction again.</li></ol><div class="callout"><strong>Be helpful:</strong> say “I was unsure where to turn” rather than “This is wrong.”</div></article><article class="lesson-card"><h3>What happened?</h3>${qInput('peer_name','Partner’s first name')}${qText('peer_original','Copy the direction your partner found difficult.',2,'My original direction was…')}${qText('peer_feedback','Why was it difficult to follow?',2,'My partner was unsure because…')}${qText('peer_improved','Write your clearer direction.',2,'My improved direction is…')}${check('peer_retested','My partner followed the changed direction again.')}</article></div>`},
plenary(){return `${sectionHeader('Plenary — What did you learn?','5 minutes','Complete four short sentences and check that today’s work is saved.')}<div class="card-grid"><article class="lesson-card"><h3>Finish the sentences</h3>${qText('plenary_decomp','Splitting the First-Day Tour into four smaller journeys helped because…',2)}${qText('plenary_abstract','The simplified map helped because it kept… and removed…',2)}${qText('plenary_ipo','The output of the First-Day Tour program was…',2)}${qText('plenary_next','Next lesson, I would like help with…',2)}</article><article class="lesson-card"><h3>Before you finish</h3>${check('final_brief','I explained the First-Day School Tour program.')}${check('final_criteria','I wrote four rules for the blue route line.')}${check('final_ipo','I explained the input, process and output of this exact program.')}${check('final_route','I planned Journeys 2, 3 and 4 after reading the Journey 1 example.')}${check('final_pseudo','I joined the four journeys into complete pseudocode.')}${check('final_test','A partner tested one direction and I improved it.')}${check('final_python','I ran the Python code, captured my work and downloaded my Python file.')}</article></div>`},
review(){return reviewHtml()}
};

function filename(label,ext){const klass=(state?.klass||'Class').replace(/[^a-z0-9]/gi,'');const name=(state?.name||'Name').split(/\s+/).filter(Boolean).join('_').replace(/[^a-z0-9_]/gi,'');return `Y7_${klass}_${name}_W2_${label}_v01.${ext}`}
function lessonMap(caption='This is the map you will use today.'){
  return `<figure class="working-map"><img src="assets/school_map_800x600.png" alt="School map showing the Main Entrance, Reception, Library, Main Stairs, Science Corridor, CS Room C1 and a staff-only area"><figcaption><strong>Read the map:</strong> 🟢 Green dot = start at the Main Entrance · 🔵 Blue dot = finish at CS Room C1 · 🔴 Red area = do not enter. ${caption}</figcaption></figure>`;
}
function turtlePreview(){return `<figure class="working-map turtle-example"><div class="map-layer"><img src="assets/school_map_800x600.png" alt="School map with a short blue Turtle line beginning at the Main Entrance"><svg viewBox="0 0 800 600" aria-hidden="true"><polyline points="260,525 205,525 205,475"/><circle cx="205" cy="475" r="8"/><text x="215" y="465">Turtle has drawn this blue line</text></svg></div><figcaption><strong>Example output:</strong> Turtle acts like a digital pen. The code moves it from the green start to other points, leaving a blue line behind. Your finished route will use more points to reach CS Room C1.</figcaption></figure>`}
function contextualStarter(){return `${sectionHeader('Starter — A new student needs your help','8 minutes','Read the situation and study the map before answering.')}<article class="lesson-card scenario-reading"><span class="read-tag">Read this first</span><h3>Sam’s first Computer Science lesson</h3><p>Sam has just joined Year 7. Sam enters through the <strong>Main Entrance</strong> and needs to get to <strong>CS Room C1</strong>.</p><p>Sam has never walked through this school before. Sam needs a route that is easy to follow and does not go through the <strong>STAFF ONLY</strong> room.</p><p><strong>Your job today:</strong> plan written directions for Sam and use a small Python program to draw part of the route as a blue line on this map.</p></article>${lessonMap('The black lines are walls. The white spaces between rooms are the corridors Sam can use.')}<div class="card-grid"><article class="lesson-card"><h3>Check that you understand the job</h3>${qInput('starter_decomp','1. Where does Sam start?','Sam starts at…')}${qInput('starter_abstract','2. Where must Sam finish?','Sam must finish at…')}${qInput('starter_ipo','3. Which area must the route avoid?','The route must avoid…')}</article><article class="lesson-card"><h3>What will you make?</h3><fieldset class="question"><legend>Choose the best description of today’s work.</legend><label class="choice"><input type="radio" name="abstraction-choice" value="all" data-answer="starter_choice"> I will build a live phone GPS app.</label><label class="choice"><input type="radio" name="abstraction-choice" value="useful" data-answer="starter_choice"> I will plan directions and use Python Turtle to draw part of the route on the given map.</label><label class="choice"><input type="radio" name="abstraction-choice" value="none" data-answer="starter_choice"> I will draw a new school building.</label></fieldset><button class="small-button" data-action="check-starter">Check my answer</button><div id="starter-feedback" class="feedback hidden" role="status"></div></article></div>`}
function tourScenario(){return `<article class="lesson-card scenario-reading"><span class="read-tag">Project scenario</span><h3>Sam’s First-Day School Tour</h3><p>Sam cannot go straight to CS Room C1. Before the lesson, Sam must:</p><ol><li>Start at the <strong>Main Entrance</strong>.</li><li>Visit <strong>Reception</strong> to collect a timetable.</li><li>Visit the <strong>Library</strong> to collect a library card.</li><li>Pass the <strong>Main Stairs</strong> and enter the <strong>Science Corridor</strong>.</li><li>Finish at <strong>CS Room C1</strong>.</li></ol><p>The route must follow this order and must not enter <strong>STAFF ONLY</strong>.</p></article>`}
function contextualStarter(){return `${sectionHeader('Starter — A new student needs your help','6 minutes','Read Sam’s full first-day problem and study the map before answering.')} ${tourScenario()} ${lessonMap('The black lines are walls. The white spaces between rooms are the corridors Sam can use.')}<div class="card-grid"><article class="lesson-card"><h3>Check that you understand the tour</h3>${qInput('starter_decomp','1. Where does Sam start?','Sam starts at…')}${qInput('starter_abstract','2. Where does Sam finish?','Sam finishes at…')}${qInput('starter_ipo','3. Name the two places where Sam must collect something.','Sam must visit… and…')}</article><article class="lesson-card"><h3>What will you make?</h3><fieldset class="question"><legend>Choose the best description.</legend><label class="choice"><input type="radio" name="abstraction-choice" value="all" data-answer="starter_choice"> A live phone GPS app for any destination.</label><label class="choice"><input type="radio" name="abstraction-choice" value="useful" data-answer="starter_choice"> A First-Day School Tour program that draws Sam’s required route on the given map.</label><label class="choice"><input type="radio" name="abstraction-choice" value="none" data-answer="starter_choice"> A new plan for rebuilding the school.</label></fieldset><button class="small-button" data-action="check-starter">Check my answer</button><div id="starter-feedback" class="feedback hidden" role="status"></div></article></div>`}
function contextualBrief(){return `${sectionHeader('The program you will create','6 minutes','Understand exactly what the First-Day School Tour program will do.')}<div class="card-grid"><article class="lesson-card"><h3>Python Turtle is a digital pen</h3><p><strong>Python</strong> is a language for writing computer instructions.</p><p><strong>Turtle</strong> is an on-screen pointer that acts like a pen. Each <code>goto</code> command sends it to another point on the map. It leaves a blue line behind.</p><pre class="code-review">route.goto(-140, -225)
route.goto(-200, -225)</pre><p>The program contains route points in the required order. Python reads them from top to bottom and Turtle joins them with a blue line.</p></article><article class="lesson-card"><h3>What the program must show</h3><ol><li>Start at the green Main Entrance dot.</li><li>Visit Reception.</li><li>Visit the Library.</li><li>Pass the Main Stairs and Science Corridor.</li><li>Finish at the blue CS Room C1 dot.</li><li>Avoid STAFF ONLY and all walls.</li></ol></article><article class="lesson-card full">${turtlePreview()}</article><article class="lesson-card"><h3>Explain the program</h3>${qInput('brief_user','Who will use the route?','Sam, a new Year 7 student')}${qText('brief_purpose','Why must Sam visit several places?',2,'Sam must collect…')}${qText('brief_product','What will the First-Day School Tour program display?',3,'The program will display…')}</article><article class="lesson-card"><h3>Four rules for the program</h3><p>Complete each sentence so another student can test the finished program.</p>${qInput('criteria_1','1. The blue line must start…','at the green Main Entrance dot.')}${qInput('criteria_2','2. The blue line must visit…','Reception, Library, Main Stairs and Science Corridor, in that order.')}${qInput('criteria_3','3. The blue line must finish…','at the blue CS Room C1 dot.')}${qInput('criteria_4','4. The blue line must not…','enter STAFF ONLY or cross a wall.')}</article></div>`}
function contextualMain1(){return `${sectionHeader('Main Task 1 — Plan the First-Day Tour','12 minutes','Split the required tour into smaller journeys and decide what information the program needs.')} ${tourScenario()} <div class="card-grid"><article class="lesson-card full"><span class="read-tag">Part A — Decomposition</span><h3>Why split this tour?</h3><p>Sam has several jobs to complete. If we write one long instruction from the entrance to C1, we may forget a stop or put the stops in the wrong order.</p><p>We therefore make four smaller journeys:</p><ol class="journey-list"><li><strong>Journey 1:</strong> Main Entrance → Reception <span>collect timetable</span></li><li><strong>Journey 2:</strong> Reception → Library <span>collect library card</span></li><li><strong>Journey 3:</strong> Library → Main Stairs <span>reach the correct stairs</span></li><li><strong>Journey 4:</strong> Main Stairs → Science Corridor → CS Room C1 <span>arrive for the lesson</span></li></ol><p>This is <strong>decomposition</strong>: split a larger problem into smaller jobs that can be planned and tested separately.</p>${qText('decomp_reason','Why is splitting Sam’s tour useful?',2,'It helps us…')}</article><article class="lesson-card full"><span class="read-tag">Part B — Abstraction</span><h3>Which map is easier to use?</h3>${image('image-03-useful-abstraction.png','Comparison of an overloaded school map and a simplified map containing only route information')}<ol><li>Look at the overloaded map on the left.</li><li>Look at the simplified map on the right.</li><li>Notice which details disappeared and which details stayed.</li></ol><p><strong>Abstraction</strong> means keeping information that helps the task and removing information that does not help.</p>${qText('abstract_keep','Write three things the route map should KEEP.',2,'Keep: room names, …')}${qText('abstract_remove','Write three things the route map should REMOVE.',2,'Remove: decorations, …')}${qText('abstract_reason','Why will the simpler map help Sam?',2,'The simpler map will help because…')}</article><article class="lesson-card full"><span class="read-tag">Part C — The program</span><h3>What are we programming?</h3><p>You are creating one <strong>First-Day School Tour program</strong>. The program contains coordinate points for all four smaller journeys. Python reads the points in order. Turtle joins them to draw one complete blue route.</p><div class="ipo-flow"><div><strong>INPUT</strong><span>The simplified map and ordered coordinate points written in the Python file</span></div><div aria-hidden="true">→</div><div><strong>PROCESS</strong><span>Python reads each point; Turtle moves from point to point in the correct order</span></div><div aria-hidden="true">→</div><div><strong>OUTPUT</strong><span>One blue First-Day Tour line visiting every required stop</span></div></div></article><article class="lesson-card full"><h3>Now write about this exact program</h3><p>Use the model above. Do not describe any program you can imagine; describe Sam’s <strong>First-Day School Tour program</strong>.</p>${qText('ipo_input','INPUT — What two things are already given to the program?',2,'The program is given the simplified school map and…')}${qText('ipo_process','PROCESS — What will Python and Turtle do with the points?',2,'Python will read… Turtle will…')}${qText('ipo_output','OUTPUT — What exactly will appear on the screen?',2,'The screen will show one blue line that visits…')}</article></div>`}
function journeyPlanner(n,title,start,finish,purpose,prompt,example=''){return `<article class="lesson-card journey-planner"><span class="read-tag">Journey ${n}</span><h3>${title}</h3><p><strong>Start:</strong> ${start}<br><strong>Finish:</strong> ${finish}<br><strong>Why Sam goes there:</strong> ${purpose}</p><div class="think-steps"><strong>Think before writing:</strong><ol><li>Find ${start} and ${finish} on the map.</li><li>Use your finger to trace a corridor between them.</li><li>Notice every door, turn or named place Sam needs.</li><li>Write one action per line. Do not skip a turn.</li></ol></div>${qText(`journey_${n}_plan`,prompt,4,example||'MOVE…\nTURN…\nSTOP…')}</article>`}
function contextualMain2(){return `${sectionHeader('Main Task 2 — Write each smaller journey','18 minutes','Study one journey at a time. Use the thinking steps and worked example before joining all four parts.')}<article class="lesson-card full">${lessonMap('Keep this map visible. Trace each journey with your finger before you write.')}</article><div class="card-grid"><article class="lesson-card full worked-example"><span class="read-tag">Journey 1 — Worked example</span><h3>Main Entrance → Reception</h3><p>Sam starts on the green dot and needs to collect the timetable from Reception.</p><div class="worked-columns"><div><h4>How to think</h4><ol><li>Find the green Main Entrance dot.</li><li>Find the Reception door.</li><li>Trace the bottom corridor from right to left.</li><li>Stop outside Reception; do not draw through its wall.</li></ol></div><div><h4>Pseudocode</h4><pre class="code-review">START at the green Main Entrance dot
FACE towards Reception
MOVE left along the bottom corridor
STOP outside the Reception door</pre></div></div><p><strong>Why this is clear:</strong> every line begins with an action and says where Sam should move or stop.</p></article>${journeyPlanner(2,'Reception → Library','outside Reception','outside the Library','collect a library card','Write the directions for Journey 2. How does Sam leave Reception, move through the corridor and stop outside the Library?','START outside Reception\nMOVE…')}${journeyPlanner(3,'Library → Main Stairs','outside the Library','at the Main Stairs','reach the stairs needed for the next part','Write the directions for Journey 3. Include the direction of the turn and where Sam should stop.','START outside the Library\nTURN…')}${journeyPlanner(4,'Main Stairs → CS Room C1','at the Main Stairs','at the blue CS Room C1 dot','reach the Computer Science lesson','Write the directions for Journey 4. Include the Science Corridor and keep away from STAFF ONLY.','START at the Main Stairs\nMOVE into the Science Corridor\n…')}<article class="lesson-card full"><h3>Join the four journeys</h3><p>Copy the worked Journey 1, then add your Journeys 2, 3 and 4 underneath it. The final pseudocode must show every required stop in order.</p>${qText('pseudocode','Write the complete First-Day School Tour pseudocode.',14,'START at the green Main Entrance dot\nFACE towards Reception\nMOVE left along the bottom corridor\nSTOP outside the Reception door\n\nSTART Journey 2…\n\nSTOP at the blue CS Room C1 dot')}</article><article class="lesson-card"><h3>Final route check</h3>${qText('map_plan','List Sam’s required places in the exact order your pseudocode visits them.',3,'Main Entrance → Reception → …')}${check('route_all_stops','My pseudocode includes Reception, Library, Main Stairs, Science Corridor and CS Room C1.')}${check('route_safe','My pseudocode does not send Sam through STAFF ONLY or through a wall.')}</article><article class="lesson-card"><h3>Optional: add a marked map</h3><p>If you drew the route on paper or marked a digital copy, add a photo or screenshot.</p><label for="evidence-upload">Add map image</label><input id="evidence-upload" type="file" accept="image/*"><img id="upload-preview" class="upload-preview hidden" alt="Student’s uploaded route plan"><button class="small-button" data-action="remove-upload">Remove image</button><p id="upload-message" class="feedback hidden"></p></article></div>`}
function simplifyPythonPage(html){
  return html
    .replace("Turtle preview — Turn part of the plan into code","Python Turtle — Draw part of your route")
    .replace("Use the built-in Python editor to preview and improve the planned route.","Choose points on the map and tell Turtle where to move.")
    .replace(/<p class="callout"><strong>This is a preview, not the full Week 3 implementation\.<\/strong>[\s\S]*?<\/p>/,'')
    .replace("How to read <code>goto(x, y)</code>","First, understand <code>goto(x, y)</code>")
    .replace("<strong>x comes first:</strong> negative x moves left; positive x moves right. <strong>y comes second:</strong> negative y moves down; positive y moves up.","<strong>x is the first number:</strong> minus moves left and plus moves right. <strong>y is the second number:</strong> minus moves down and plus moves up.")
    .replace("Example: <code>route.goto(-250, -225)</code> means move to x = −250 and y = −225.","<code>route.goto(-250, -225)</code> means: go to x = -250, y = -225.")
    .replace("<li>Run the starter code.</li><li>Use the coordinate grid and pointer readout to choose route points.</li><li>Add at least three route movement commands using <code>goto(x, y)</code>, <code>forward()</code> or turns.</li><li>Keep the route away from STAFF ONLY.</li><li>Capture evidence and download the Python file.</li>","<li>Select <strong>Run</strong> once.</li><li>Point at the map to see the x and y numbers.</li><li>Select a safe point to copy its <code>goto</code> command.</li><li>Paste the command below the comment in the editor.</li><li>Repeat for at least three points, then run it again.</li><li>Keep the line inside corridors and outside STAFF ONLY.</li>")
    .replace(/<p><strong>Background image note:<\/strong>[\s\S]*?<\/p>/,'')
    .replace("Explain how your code represents at least one section of your planned route.","Which two points does one of your goto commands connect?")
    .replace("What did you change after viewing the route on the map?","What did you change to make the line safer or clearer?");
}
function prepareLearningSteps(sectionId){
  const labels=sectionId==='main1'?['A. Split the tour (decomposition)','B. Simplify the map (abstraction)','C. Understand the program','D. Write the program’s IPO']:sectionId==='main2'?['1. Read the worked example','2. Plan Journey 2','3. Plan Journey 3','4. Plan Journey 4','5. Join all four journeys','6. Complete the final check','7. Optional map evidence']:null;
  if(!labels)return;const scope=sectionId==='main2'?document.querySelector('.lesson-section .card-grid'):document.querySelector('.lesson-section .card-grid');if(!scope)return;const cards=[...scope.children].filter(n=>n.matches('article.lesson-card'));
  cards.forEach((card,i)=>{const details=document.createElement('details');details.className='learning-step';details.open=i===0;const summary=document.createElement('summary');summary.innerHTML=`<span>${labels[i]||`Step ${i+1}`}</span><small>${i===0?'Start here':'Open when ready'}</small>`;details.append(summary);card.replaceWith(details);details.append(card);details.addEventListener('toggle',()=>{if(details.open){details.querySelector('small').textContent='Currently open';[...scope.querySelectorAll(':scope > details.learning-step')].forEach(other=>{if(other!==details)other.open=false})}else details.querySelector('small').textContent='Open when ready';});});
}
function render(){
  const s=sections[current];let sectionHtml=s.id==='starter'?contextualStarter():s.id==='brief'?contextualBrief():s.id==='main1'?contextualMain1():s.id==='main2'?contextualMain2():renderers[s.id]();if(s.id==='python')sectionHtml=simplifyPythonPage(sectionHtml);el('section-host').innerHTML=`<section class="lesson-section" data-section="${s.id}">${sectionHtml}</section>`;prepareLearningSteps(s.id);
  el('header-name').textContent=state.name;el('header-class').textContent=state.teacher?'':state.klass;
  hydrateSpecial();bindInputs();renderNav();updateProgress();
  el('back-button').disabled=current===0;el('next-button').textContent=current===sections.length-1?'Stay on review':'Save and continue';
  window.scrollTo({top:0,behavior:'smooth'});
}
function hydrateSpecial(){
  document.querySelectorAll('input[type=radio][data-answer]').forEach(n=>n.checked=answer(n.dataset.answer)===n.value);
  if(el('python-code')){el('python-code').value=state.code||defaultCode;el('python-code').addEventListener('keydown',codeKeys);el('python-code').addEventListener('input',e=>{state.code=e.target.value;log('code','python-code',e.target.value)});el('python-console').textContent=state.lastOutput||'Python Turtle is ready.';setupCoordinateGrid();if(state.pythonEvidence){el('python-evidence').src=state.pythonEvidence;el('python-evidence').classList.remove('hidden')}}
  if(el('evidence-upload'))el('evidence-upload').addEventListener('change',uploadImage);
  if(el('upload-preview')&&state.uploadedEvidence){el('upload-preview').src=state.uploadedEvidence;el('upload-preview').classList.remove('hidden')}
}
function renderNav(){el('journey-nav').innerHTML=sections.map((s,i)=>`<button data-index="${i}" class="${i===current?'current ':''}${state.completed[s.id]?'complete':''}" ${(!teacher&&i>maxUnlocked())?'disabled':''}>${s.label}</button>`).join('');document.querySelectorAll('#journey-nav button').forEach(b=>b.addEventListener('click',()=>{collectVisible();current=+b.dataset.index;state.current=current;log('navigate',sections[current].id,'nav');render()}))}
function maxUnlocked(){if(teacher)return sections.length-1;for(let i=0;i<sections.length-1;i++){if(!state.completed[sections[i].id])return i}return sections.length-1}
function updateProgress(){const done=sections.slice(0,-1).filter(s=>state.completed[s.id]).length;const pct=Math.round(done/(sections.length-1)*100);el('progress-bar').style.width=pct+'%';el('progress-text').textContent=`${pct}% complete · ${done}/${sections.length-1} core sections`;}
function validate(id){
  collectVisible();if(teacher)return [];
  const a=state.answers,c=state.checks,miss=[];
  const need=(cond,msg)=>{if(!cond)miss.push(msg)};
  if(id==='welcome'){need(c.welcome_folder&&c.welcome_wagba&&c.welcome_files,'Tick all three setup confirmations.');}
  if(id==='starter'){need(/main entrance/i.test(a.starter_decomp||''),'Write that Sam starts at the Main Entrance.');need(/c1|cs room/i.test(a.starter_abstract||''),'Write that Sam finishes at CS Room C1.');need(/reception/i.test(a.starter_ipo||'')&&/library/i.test(a.starter_ipo||''),'Write Reception and Library as the two collection stops.');need(a.starter_choice==='useful','Choose the description that matches today’s work.');}
  if(id==='brief'){need(clean(a.brief_user).length>=5,'Write who you are helping.');need(clean(a.brief_purpose).length>=20,'Explain why the new student needs the route.');need(clean(a.brief_product).length>=25,'Explain what you will make today.');need([1,2,3,4].every(i=>clean(a[`criteria_${i}`]).length>=12),'Complete all four “The route must…” sentences.');}
  if(id==='main1'){need(clean(a.decomp_reason).length>=20,'Explain why the tour is split into smaller journeys.');need(clean(a.abstract_keep).length>=20,'Write three useful details to keep.');need(clean(a.abstract_remove).length>=20,'Write three distracting details to remove.');need(clean(a.abstract_reason).length>=20,'Explain why the simpler map helps Sam.');need(['ipo_input','ipo_process','ipo_output'].every(k=>clean(a[k]).length>=25),'Complete the three sentences about the First-Day School Tour program.');}
  if(id==='main2'){need([2,3,4].every(i=>clean(a[`journey_${i}_plan`]).split(/\n/).filter(Boolean).length>=2),'Write at least two clear instruction lines for Journeys 2, 3 and 4.');need(clean(a.pseudocode).split(/\n/).filter(Boolean).length>=10,'Join the four journeys into at least ten pseudocode lines.');need(/reception/i.test(a.map_plan||'')&&/library/i.test(a.map_plan||'')&&/stairs/i.test(a.map_plan||'')&&/c1|cs room/i.test(a.map_plan||''),'List every required stop in the correct order.');need(c.route_all_stops&&c.route_safe,'Complete both final route checks.');}
  if(id==='python'){need(state.runCount>=1,'Run the Python Turtle code at least once.');need(clean(state.code).length>defaultCode.length+15,'Add at least some route code of your own.');need(clean(a.python_explain).length>=20,'Explain how the code represents your route.');need(clean(a.python_improve).length>=12,'Record an improvement after viewing the result.');need(!!state.pythonEvidence,'Capture your Python and Turtle evidence.');}
  if(id==='peer'){need(clean(a.peer_name).length>=2,'Enter the tester’s first name.');need(['peer_original','peer_feedback','peer_improved'].every(k=>clean(a[k]).length>=10),'Record the original instruction, feedback and improvement.');need(c.peer_retested,'Confirm that the improved instruction was retested.');}
  if(id==='plenary'){need(['plenary_decomp','plenary_abstract','plenary_ipo','plenary_next'].every(k=>clean(a[k]).length>=12),'Complete all four exit-ticket reflections.');need(['final_brief','final_criteria','final_ipo','final_route','final_pseudo','final_test','final_python'].every(k=>c[k]),'Complete the final achievement check.');}
  return miss;
}
function next(){
  const id=sections[current].id;if(id==='review')return;
  const errors=validate(id);if(errors.length){showErrors(errors);return;}
  state.completed[id]=true;log('complete',id,true);if(current<sections.length-1){current++;state.current=current;save(true);render()}
}
function showErrors(errors){let box=document.querySelector('.section-error');if(!box){box=document.createElement('div');box.className='feedback warn section-error';box.setAttribute('role','alert');document.querySelector('.lesson-section header').after(box)}box.innerHTML=`<strong>Before continuing:</strong><ul>${errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;box.scrollIntoView({behavior:'smooth',block:'center'})}

function action(name){
  log('click',name,true);
  if(name==='check-starter'){const box=el('starter-feedback');const ok=state.answers.starter_choice==='useful';box.className='feedback '+(ok?'good':'warn');box.textContent=ok?'Correct. You are creating one First-Day School Tour program for Sam’s required stops.':'Not yet. Read the scenario again: Sam has several required stops, and your program will draw that tour on the given map.';}
  if(name==='ipo-hint')el('ipo-hint').classList.remove('hidden');
  if(name==='remove-upload'){state.uploadedEvidence='';if(el('upload-preview'))el('upload-preview').classList.add('hidden');save()}
  if(name==='run-python')runPython();
  if(name==='stop-python')stopPython();
  if(name==='toggle-grid')toggleCoordinateGrid();
  if(name==='reset-python'){if(confirm('Reset the editor to the starter code? Your current code will be replaced.')){state.code=defaultCode;el('python-code').value=defaultCode;log('code-reset','python-code',true)}}
  if(name==='clear-output'){state.lastOutput='';el('python-console').textContent='';clearTurtle();save()}
  if(name==='download-python')downloadText(filename('WayfindingPlan','py'),state.code||defaultCode,'text/x-python');
  if(name==='capture-python')capturePython();
  if(name==='export-pdf')exportPdf();
  if(name==='print-report')window.print();
  if(name==='download-json')downloadText(filename('EvidenceBackup','json'),JSON.stringify(state,null,2),'application/json');
}
function codeKeys(e){if(e.key==='Tab'){e.preventDefault();const s=e.target.selectionStart,end=e.target.selectionEnd;e.target.setRangeText('    ',s,end,'end');e.target.dispatchEvent(new Event('input'))}if(e.key==='Enter'&&e.ctrlKey){e.preventDefault();runPython()}}
function normalisePython(code){
  const replacements=[[/[−–—]/g,'-'],[/[“”]/g,'"'],[/[‘’]/g,"'"],[/\u00a0/g,' '],[/，/g,','],[/（/g,'('],[/）/g,')']];let fixed=String(code),changes=[];
  for(const [pattern,value] of replacements){const before=fixed;fixed=fixed.replace(pattern,value);if(fixed!==before)changes.push(`${pattern} → ${value}`)}
  return{code:fixed,changed:changes.length>0};
}
function selectCodeLine(lineNumber){const editor=el('python-code');if(!editor||!lineNumber)return;const lines=editor.value.split('\n');let start=0;for(let i=0;i<lineNumber-1;i++)start+=lines[i].length+1;const end=start+(lines[lineNumber-1]||'').length;editor.focus();editor.setSelectionRange(start,end);}
function friendlyPythonError(err){
  const raw=String(err),match=raw.match(/line\s+(\d+)/i),line=match?Number(match[1]):null;let help='Read the named line carefully, correct it, and run the program again.';
  if(/bad token|T_OP|invalid character/i.test(raw))help='Python found a character it cannot read. Use the keyboard minus sign (-), straight quotation marks ("), ordinary commas, and ordinary brackets. Do not use the longer symbol (−) copied from formatted text.';
  else if(/indent/i.test(raw))help='Check the spaces at the beginning of this line. Commands at the same level should line up.';
  else if(/bad input|EOF|was never closed|unexpected/i.test(raw))help='Check for a missing bracket, quotation mark or comma near this line.';
  else if(/NameError/i.test(raw))help='Check the spelling and capital letters in the name used on this line.';
  return{line,message:`Your program needs one correction${line?` on line ${line}`:''}.\n${help}\n\nTechnical detail: ${raw}`};
}
function drawCoordinateGrid(){
  const canvas=el('coordinate-grid');if(!canvas)return;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,800,600);ctx.save();ctx.font='bold 11px Arial';ctx.textAlign='center';ctx.textBaseline='top';
  for(let x=-350;x<=350;x+=50){const px=400+x;ctx.beginPath();ctx.strokeStyle=x===0?'rgba(20,87,217,.9)':'rgba(20,87,217,.25)';ctx.lineWidth=x===0?2:1;ctx.moveTo(px,0);ctx.lineTo(px,600);ctx.stroke();ctx.fillStyle='#0c398f';if(x!==0)ctx.fillText(String(x),px,306)}
  ctx.textAlign='left';ctx.textBaseline='middle';for(let y=-250;y<=250;y+=50){const py=300-y;ctx.beginPath();ctx.strokeStyle=y===0?'rgba(20,87,217,.9)':'rgba(20,87,217,.25)';ctx.lineWidth=y===0?2:1;ctx.moveTo(0,py);ctx.lineTo(800,py);ctx.stroke();ctx.fillStyle='#0c398f';if(y!==0)ctx.fillText(String(y),405,py)}
  ctx.font='bold 16px Arial';ctx.fillStyle='#0c398f';ctx.textAlign='right';ctx.fillText('+x',790,286);ctx.textAlign='left';ctx.fillText('−x',10,286);ctx.textAlign='left';ctx.fillText('+y',407,14);ctx.fillText('−y',407,586);ctx.beginPath();ctx.fillStyle='#0c398f';ctx.arc(400,300,4,0,Math.PI*2);ctx.fill();ctx.font='bold 12px Arial';ctx.fillText('(0, 0)',408,315);ctx.restore();
}
function mapCoords(e){const rect=el('turtle-stage').getBoundingClientRect();const px=(e.clientX-rect.left)*800/rect.width,py=(e.clientY-rect.top)*600/rect.height;return{x:Math.max(-400,Math.min(400,Math.round((px-400)/10)*10)),y:Math.max(-300,Math.min(300,Math.round((300-py)/10)*10)),px,py}}
function setupCoordinateGrid(){
  drawCoordinateGrid();const stage=el('turtle-stage'),readout=el('coordinate-readout'),cross=el('coordinate-crosshair');if(!stage)return;el('map-cover')?.classList.add('hidden');
  stage.addEventListener('pointermove',e=>{const p=mapCoords(e);readout.innerHTML=`Pointer coordinate: <strong>x = ${p.x}, y = ${p.y}</strong> · Python: <code>route.goto(${p.x}, ${p.y})</code>`;cross.style.left=`${p.px}px`;cross.style.top=`${p.py}px`;cross.querySelector('span').textContent=`(${p.x}, ${p.y})`;cross.classList.remove('hidden')});
  stage.addEventListener('pointerleave',()=>cross.classList.add('hidden'));
  stage.addEventListener('click',e=>{const p=mapCoords(e),command=`route.goto(${p.x}, ${p.y})`;readout.innerHTML=`Selected: <strong>x = ${p.x}, y = ${p.y}</strong> · <code>${command}</code> copied to your clipboard.`;navigator.clipboard?.writeText(command).catch(()=>{});log('coordinate-selected','map',command)});
}
function toggleCoordinateGrid(){const grid=el('coordinate-grid'),button=document.querySelector('[data-action="toggle-grid"]');if(!grid)return;const hidden=grid.classList.toggle('hidden');button.textContent=hidden?'Show coordinate grid':'Hide coordinate grid';button.setAttribute('aria-pressed',String(!hidden));log('coordinate-grid','visible',!hidden)}
function clearTurtle(){const target=el('turtle-output');if(target)target.innerHTML='';const cover=el('map-cover');if(cover)cover.classList.add('hidden')}
function preprocess(code){return code.split('\n').map(line=>(/^\s*(?:\w+\.)?bgpic\s*\(/.test(line)||/^\s*(?:t\.)?done\s*\(/.test(line))?'':line).join('\n')}
function builtinRead(x){if(Sk.builtinFiles===undefined||Sk.builtinFiles.files[x]===undefined)throw new Error(`File not found: ${x}`);return Sk.builtinFiles.files[x]}
function runPython(){
  if(running)return;collectVisible();const normalised=normalisePython(state.code);if(normalised.changed){state.code=normalised.code;el('python-code').value=normalised.code;save(true)}clearTurtle();el('map-cover').classList.add('hidden');const out=el('python-console');out.textContent=normalised.changed?'Running…\nI replaced copied typographic symbols with Python-safe keyboard characters.\n':'Running…\n';running=true;state.runCount++;
  try{Sk.pre='turtle-output';Sk.TurtleGraphics={target:'turtle-output',width:800,height:600};Sk.configure({output:t=>{out.textContent+=t;state.lastOutput=out.textContent},read:builtinRead,__future__:Sk.python3,execLimit:8000});const code=preprocess(state.code);Sk.misceval.asyncToPromise(()=>Sk.importMainWithBody('<student>',false,code,true)).then(()=>{running=false;out.textContent+=(out.textContent.endsWith('\n')?'':'\n')+`Run ${state.runCount} finished. The webpage kept school_map.gif behind the Turtle canvas.`;state.lastOutput=out.textContent;log('python-run','success',state.runCount)},err=>{running=false;const friendly=friendlyPythonError(err);out.textContent+='\n'+friendly.message;state.lastOutput=out.textContent;selectCodeLine(friendly.line);log('python-run','error',String(err));save()})}catch(err){running=false;const friendly=friendlyPythonError(err);out.textContent+='\n'+friendly.message;state.lastOutput=out.textContent;selectCodeLine(friendly.line);save()}
}
function stopPython(){if(!running){if(el('python-console'))el('python-console').textContent+='\nNo program is currently running.';return}running=false;clearTurtle();el('python-console').textContent+='\nExecution stopped. If necessary, reset and run again.';state.lastOutput=el('python-console').textContent;save()}
async function capturePython(){
  collectVisible();const b=document.querySelector('[data-action="capture-python"]');const old=b.textContent;b.textContent='Capturing…';b.disabled=true;
  try{const stage=el('turtle-stage');const stageCanvas=await html2canvas(stage,{backgroundColor:'#fff',scale:1,useCORS:false});const wrapper=document.createElement('div');wrapper.style.cssText='position:fixed;left:-10000px;top:0;width:1100px;background:white;color:black;padding:28px;font-family:Arial';wrapper.innerHTML=`<h2>Year 7 Week 2 Python Turtle Evidence</h2><p><strong>${esc(state.name)}</strong> · ${esc(state.klass)} · ${new Date().toLocaleString()}</p><div style="display:grid;grid-template-columns:1fr 800px;gap:18px"><pre style="white-space:pre-wrap;border:1px solid #111;padding:12px;font:13px/1.4 monospace">${esc(state.code)}</pre><img src="${stageCanvas.toDataURL('image/png')}" style="width:800px;height:600px;border:1px solid #111"></div>`;document.body.appendChild(wrapper);const capture=await html2canvas(wrapper,{backgroundColor:'#fff',scale:.8});state.pythonEvidence=capture.toDataURL('image/jpeg',.88);wrapper.remove();el('python-evidence').src=state.pythonEvidence;el('python-evidence').classList.remove('hidden');log('evidence','python-capture','captured')}catch(err){alert('Evidence capture could not finish in this browser. Try running the app through static hosting, or use your device screenshot tool and add the image in Main Task 2.');log('evidence-error','python-capture',String(err))}finally{b.textContent=old;b.disabled=false;save(true)}
}
function uploadImage(e){const file=e.target.files[0];if(!file)return;if(file.size>12*1024*1024){el('upload-message').textContent='Choose an image smaller than 12 MB.';el('upload-message').classList.remove('hidden');return}const rd=new FileReader();rd.onload=()=>{const img=new Image();img.onload=()=>{const max=1200,scale=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);state.uploadedEvidence=c.toDataURL('image/jpeg',.78);el('upload-preview').src=state.uploadedEvidence;el('upload-preview').classList.remove('hidden');el('upload-message').textContent='Planning evidence added and saved locally.';el('upload-message').classList.remove('hidden');log('upload','planning-image',file.name)};img.src=rd.result};rd.readAsDataURL(file)}
function downloadText(name,textValue,type){const blob=new Blob([textValue],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);log('download',name,type)}
function reviewHtml(){
  const a=state.answers,c=state.checks;const block=(title,body)=>`<section class="review-block"><h3>${title}</h3>${body}</section>`;const val=k=>esc(a[k]||'Not attempted');
  return `${sectionHeader('Evidence review and export','Final stage','Check your evidence, download the required files and upload them to Teams.')}<div id="report-content"><div class="teams-box"><h3>Microsoft Teams submission</h3><p>Upload your <strong>PDF evidence report</strong> and <strong>Python .py file</strong> to the Microsoft Teams Assignment named <strong>Week 2 Practical</strong>.</p></div>${block('Student and lesson',`<p><strong>${esc(state.name)}</strong> · ${esc(state.klass)} · ${new Date().toLocaleDateString()}</p><p><strong>WAGBA:</strong> Plan and test a First-Day School Tour that takes a new student to several required places in the correct order, then use Python Turtle to draw the route.</p>`)}${block('Starter understanding',`<p><strong>Start:</strong> ${val('starter_decomp')}</p><p><strong>Finish:</strong> ${val('starter_abstract')}</p><p><strong>Collection stops:</strong> ${val('starter_ipo')}</p>`)}${block('The First-Day Tour program',`<p><strong>User:</strong> ${val('brief_user')}</p><p><strong>Why several stops are required:</strong> ${val('brief_purpose')}</p><p><strong>Program output:</strong> ${val('brief_product')}</p><ol>${[1,2,3,4].map(i=>`<li>${val(`criteria_${i}`)}</li>`).join('')}</ol>`)}${block('Decomposition and abstraction',`<p><strong>Why the tour was split:</strong> ${val('decomp_reason')}</p><p><strong>Map details kept:</strong> ${val('abstract_keep')}</p><p><strong>Map details removed:</strong> ${val('abstract_remove')}</p><p><strong>Why the simpler map helps:</strong> ${val('abstract_reason')}</p>`)}${block('First-Day Tour IPO',`<p><strong>Input:</strong> ${val('ipo_input')}</p><p><strong>Process:</strong> ${val('ipo_process')}</p><p><strong>Output:</strong> ${val('ipo_output')}</p>`)}${block('Journey planning and pseudocode',`<h4>Journey 1 worked example</h4><pre class="code-review">START at the green Main Entrance dot\nFACE towards Reception\nMOVE left along the bottom corridor\nSTOP outside the Reception door</pre><h4>Journey 2</h4><pre class="code-review">${val('journey_2_plan')}</pre><h4>Journey 3</h4><pre class="code-review">${val('journey_3_plan')}</pre><h4>Journey 4</h4><pre class="code-review">${val('journey_4_plan')}</pre><p><strong>Required-stop order:</strong> ${val('map_plan')}</p><h4>Complete pseudocode</h4><pre class="code-review">${val('pseudocode')}</pre>${state.uploadedEvidence?`<img class="evidence-preview" src="${state.uploadedEvidence}" alt="Uploaded planning evidence">`:''}`)}${block('Python Turtle preview',`<p><strong>Runs:</strong> ${state.runCount}</p><pre class="code-review">${esc(state.code)}</pre><p><strong>Explanation:</strong> ${val('python_explain')}</p><p><strong>Improvement:</strong> ${val('python_improve')}</p>${state.pythonEvidence?`<img class="evidence-preview" src="${state.pythonEvidence}" alt="Python Turtle evidence">`:'<p>No captured Python evidence yet.</p>'}`)}${block('Peer testing',`<p><strong>Tester:</strong> ${val('peer_name')}</p><p><strong>Original:</strong> ${val('peer_original')}</p><p><strong>Feedback:</strong> ${val('peer_feedback')}</p><p><strong>Improved:</strong> ${val('peer_improved')}</p><p><strong>Retested:</strong> ${c.peer_retested?'Yes':'No'}</p>`)}${block('Plenary',`<p><strong>Decomposition:</strong> ${val('plenary_decomp')}</p><p><strong>Abstraction:</strong> ${val('plenary_abstract')}</p><p><strong>Output:</strong> ${val('plenary_ipo')}</p><p><strong>Next step:</strong> ${val('plenary_next')}</p>`)}</div><div class="lesson-card"><h3>Download and submit</h3><div class="export-actions"><button class="primary" data-action="export-pdf">Export PDF</button><button class="secondary" data-action="download-python">Download Python .py</button><button class="secondary" data-action="print-report">Print / Save as PDF fallback</button><button class="secondary" data-action="download-json">Download backup</button></div>${check('submit_pdf','I checked that my name, class and answers appear in the PDF.')}${check('submit_py','I checked that my Python .py file downloaded.')}${check('submit_teams','I uploaded the PDF and .py file to Teams: Week 2 Practical.')}</div>`
}
async function exportPdf(){collectVisible();const btn=document.querySelector('[data-action="export-pdf"]'),old=btn.textContent;btn.disabled=true;btn.textContent='Creating PDF…';try{const report=el('report-content'),canvas=await html2canvas(report,{scale:1.35,backgroundColor:'#fff',useCORS:false,windowWidth:1100});const {jsPDF}=window.jspdf,pdf=new jsPDF({orientation:'portrait',unit:'mm',format:'a4'}),pageW=210,pageH=297,margin=10,imgW=pageW-margin*2,imgH=canvas.height*imgW/canvas.width;let y=margin,remaining=imgH;const data=canvas.toDataURL('image/jpeg',.9);pdf.addImage(data,'JPEG',margin,y,imgW,imgH);remaining-=pageH-margin*2;while(remaining>0){pdf.addPage();y=margin-(imgH-remaining);pdf.addImage(data,'JPEG',margin,y,imgW,imgH);remaining-=pageH-margin*2}pdf.save(`Year7_${(state.klass||'Class').replace(/\W/g,'')}_${state.name.replace(/\s+/g,'_').replace(/\W/g,'')}_Week2_Practical.pdf`);log('download','pdf','success')}catch(err){alert('Direct PDF export was blocked. Use “Print / Save as PDF fallback” instead.');log('pdf-error','export',String(err))}finally{btn.disabled=false;btn.textContent=old}}
function openImage(img){el('dialog-image').src=img.src;el('dialog-image').alt=img.alt;el('image-dialog').showModal()}
function start(name,klass,isTeacher,resume=false){teacher=isTeacher;const key=keyFor(name,klass,isTeacher),saved=localStorage.getItem(key);state=(resume&&saved)?migrateSavedState(JSON.parse(saved)):fresh(name,klass,isTeacher);state.teacher=isTeacher;current=isTeacher?0:Math.min(state.current||0,maxStateIndex(state));el('landing').classList.add('hidden');el('app').classList.remove('hidden');save(true);render()}
function maxStateIndex(s){if(s.teacher)return sections.length-1;for(let i=0;i<sections.length;i++){if(!s.completed[sections[i].id])return i}return sections.length-1}

el('entry-form').addEventListener('submit',e=>{e.preventDefault();const name=clean(el('student-name').value),klass=clean(el('student-class').value),isTeacher=name.toLowerCase()==='teacher';if(!name){el('entry-error').textContent='Enter your full name.';return}if(!isTeacher&&!klass){el('entry-error').textContent='Enter your class.';return}el('entry-error').textContent='';const has=!!localStorage.getItem(keyFor(name,klass,isTeacher));start(name,klass,isTeacher,has)});
['student-name','student-class'].forEach(id=>el(id).addEventListener('input',()=>{const name=clean(el('student-name').value),klass=clean(el('student-class').value),isT=name.toLowerCase()==='teacher';el('student-class').required=!isT;el('student-class').disabled=isT;const has=name&&localStorage.getItem(keyFor(name,klass,isT));el('resume-button').classList.toggle('hidden',!has)}));
el('resume-button').addEventListener('click',()=>{const name=clean(el('student-name').value),klass=clean(el('student-class').value),isT=name.toLowerCase()==='teacher';start(name,klass,isT,true)});
el('next-button').addEventListener('click',next);el('back-button').addEventListener('click',()=>{collectVisible();if(current>0){current--;state.current=current;render()}});
el('learning-toggle').addEventListener('click',()=>{const p=document.querySelector('.learning-panel'),open=p.classList.toggle('open');el('learning-toggle').setAttribute('aria-expanded',String(open))});
el('close-image').addEventListener('click',()=>el('image-dialog').close());el('image-dialog').addEventListener('click',e=>{if(e.target===el('image-dialog'))el('image-dialog').close()});
window.addEventListener('beforeunload',()=>save(true));
})();
